def reverse_k_group(head, k):
    count = 0
    node = head
    while node and count < k:
        node = node.next
        count += 1
    if count < k:
        return head
    prev = reverse_k_group(node, k)
    while count > 0:
        nxt = head.next
        head.next = prev
        prev = head
        head = nxt
        count -= 1
    return prev

