def is_same(p, q):
    if not p and not q:
        return True
    if not p or not q:
        return False
    return p.val == q.val and is_same(p.left, q.left) and is_same(p.right, q.right)

def bfs(graph, start='G'):
    visited = set([start])
    result = []
    queue = [start]
    while queue:
        node = queue.pop(0)
        result.append(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)
    return result

