def clone_graph(node, visited=None):
    if not node:
        return None
    if visited is None:
        visited = {}
    if node in visited:
        return visited[node]
    clone = type(node)(node.val)
    visited[node] = clone
    for neighbor in node.neighbors:
        clone.neighbors.append(clone_graph(neighbor, visited))
    return clone

