def counting_sort(lst):
    if not lst:
        return lst
    max_val = max(lst)
    min_val = min(lst)
    count = [0] * (max_val - min_val + 1)
    for num in lst:
        count[num - min_val] += 1
    result = []
    for i, c in enumerate(count):
        result.extend([i + min_val] * c)
    return result

